import {renderCatalog} from './catalog.js';
import {attention,softmax,keys,values,dot,rotate,rmsNorm,cacheBytes,routeExperts} from './math.js';
const $=s=>document.querySelector(s);
const app=$('#app');
const base=new URL('../',import.meta.url).pathname;
const topic=base+'topics/ai/';
const lesson=topic+'transformers/';
const isLesson=location.pathname.includes('/transformers');
const isTopic=!isLesson&&location.pathname.includes('/topics/ai');
const chapters=[
  ['overview','The big picture','Foundations','A prediction machine.','Follow a sentence through a transformer. Each layer refines what every token knows about its context.'],
  ['tokens','Tokens & embeddings','Foundations','Language becomes geometry.','A token starts as an ID. A learned lookup turns it into a vector: numbers the network can transform.'],
  ['attention','Inside attention','Foundations','Choose. Weigh. Mix.','A query matches keys. The scores become weights. Those weights mix values into new information.'],
  ['heads','Multiple heads','Foundations','One sentence. Many views.','Each head learns its own projections. Parallel mixtures let a layer gather different information at once.'],
  ['block','The transformer block','Foundations','Communicate. Then compute.','Attention moves information between tokens. A feed-forward network transforms each token. Residual paths keep both updates.'],
  ['position','Position & RoPE','Foundations','Order needs a signal.','Attention alone cannot tell “dog bites man” from a reordered set. Position makes the arrangement visible.'],
  ['learning','Learning & generating','From model to system','Same network. Two jobs.','Training adjusts weights to predict known next tokens. Generation keeps weights fixed and extends an unknown sequence.'],
  ['efficiency','Making it efficient','From model to system','The memory problem.','Long context is expensive. Caching, shared keys and values, and better GPU kernels solve different parts of the problem.'],
  ['experts','Mixture of experts','From model to system','More capacity. Selective work.','A learned router activates only a few feed-forward networks per token. Most expert weights sit out each step.'],
  ['frontier','The evolving frontier','Beyond the original','The transformer keeps evolving.','Follow the architectural changes from 2017 to documented 2026 systems. There is no single frontier blueprint.'],
  ['check','Connect the ideas','Beyond the original','Make the model yours.','Test the mechanisms, then follow the original research wherever you want to go deeper.']
];
let current=0;
let cleanup=()=>{};
const header=()=>`<a class="skip" href="#main">Skip to content</a><header class="topbar"><a class="brand" href="${base}"><span class="brand-icon">ƒ</span>fieldnotes<span class="muted" style="font-weight:400">/</span></a><nav class="toplinks" aria-label="Main"><a href="${base}" class="${!isLesson?'active':''}">The library</a><span class="pill">A visual learning collection</span></nav></header>`;
function motif(){return `<svg viewBox="0 0 540 270" class="diagram" role="img" aria-label="Tokens connected through an attention network"><g stroke="#566b43" fill="none">${[0,1,2,3,4].flatMap(i=>[0,1,2,3,4].map(j=>`<path d="M ${90+i*90} 65 C ${90+i*90} 130 ${90+j*90} 130 ${90+j*90} 195" opacity="${i===j?.8:.22}"/>`)).join('')}</g>${[0,1,2,3,4].map((i)=>`<rect x="${64+i*90}" y="36" width="52" height="38" rx="5" fill="#28331f" stroke="#667f44"/><text x="${90+i*90}" y="61" text-anchor="middle" class="lime">${['The','next','word','is','…'][i]}</text><rect x="${64+i*90}" y="191" width="52" height="38" rx="5" fill="#273527" stroke="#c5f277"/>${Array.from({length:5},(_,j)=>`<rect x="${70+i*90+j*8}" y="${201+j%2*4}" width="5" height="${18-j%2*8}" rx="1" fill="#c5f277" opacity="${.3+j*.14}"/>`).join('')}`).join('')}</svg>`}
function library(){renderCatalog(app,{base,aiTopic:isTopic,header,aiMotif:motif});}
function shell(){app.innerHTML=header()+`<div class="mobile-nav"><label class="small" for="chapter-select">Chapter</label><select id="chapter-select">${chapters.map((c,i)=>`<option value="${c[0]}">${String(i+1).padStart(2,'0')} · ${c[1]}</option>`).join('')}</select></div><div class="layout"><aside class="sidebar"><a class="back" href="${topic}">‹ AI & deep learning</a><h3>Inside the transformer</h3><small style="margin-left:10px">An interactive fieldnote</small><nav aria-label="Lesson chapters">${chapters.map((c,i)=>`${i===0||c[2]!==chapters[i-1][2]?`<div class="eyebrow">${c[2]}</div>`:''}<a class="chapter-link" href="#${c[0]}" data-chapter="${c[0]}"><span class="num">${String(i+1).padStart(2,'0')}</span>${c[1]}</a>`).join('')}</nav><div class="sidebar-note">Small models. Real mathematics.<br>Every experiment is illustrative.<br><br>Sources checked 06 Oct 2026.</div></aside><main id="main" class="lesson-main"></main></div>`;$('#chapter-select').onchange=e=>location.hash=e.target.value;renderChapter();}
const details=(title,body)=>`<details><summary>${title}</summary><div class="detail-body">${body}</div></details>`;
const range=(id,label,min,max,step,value,suffix='')=>`<div class="control"><label for="${id}">${label}<output id="${id}-value">${value}${suffix}</output></label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;
const tabs=(id,labels,active=0)=>`<div class="segments" id="${id}" role="group" aria-label="${id.replaceAll('-',' ')}">${labels.map((x,i)=>`<button data-value="${i}" class="${active===i?'active':''}" aria-pressed="${active===i}">${x}</button>`).join('')}</div>`;
const activate=(parent,index)=>document.querySelectorAll(`${parent} button`).forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-pressed',i===index)});
const lab=(title,content,footer='',controls='')=>`<section class="lab" aria-label="${title}"><div class="lab-head"><span class="lab-title">${title}</span>${controls}</div><div class="lab-body">${content}</div>${footer?`<div class="lab-foot">${footer}</div>`:''}</section>`;
const insight=text=>`<div class="takeaway"><span class="eyebrow">The key idea</span><p>${text}</p></div>`;
const svg=(body,label,view='0 0 820 300')=>`<div class="diagram-scroll" tabindex="0" role="region" aria-label="${label}; scroll horizontally on small screens" style="--diagram-min:${Math.min(680,+view.split(' ')[2])}px"><svg class="diagram" viewBox="${view}" role="img" aria-label="${label}">${body}</svg></div>`;
const bars=(labels,weights,color='var(--green)')=>`<div class="bars">${labels.map((l,i)=>`<div class="bar-row"><span>${l}</span><div class="bar-track"><div class="bar-fill" style="width:${weights[i]*100}%;background:${color}"></div></div><span class="bar-value">${(weights[i]*100).toFixed(1)}%</span></div>`).join('')}</div>`;
const words=['The','cat','sat','on','the','mat'];
function renderChapter(){cleanup();cleanup=()=>{};let slug=location.hash.slice(1);current=Math.max(0,chapters.findIndex(c=>c[0]===slug));const c=chapters[current];document.title=`${c[1]} · Inside the transformer — Fieldnotes`;document.querySelectorAll('.chapter-link').forEach(a=>{const active=a.dataset.chapter===c[0];a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current')});$('#chapter-select').value=c[0];$('#main').innerHTML=`<div class="breadcrumbs"><a href="${base}">Library</a><span>/</span><a href="${topic}">AI & deep learning</a><span>/</span><span>Transformers</span></div><div class="chapter-meta"><span class="eyebrow">${String(current+1).padStart(2,'0')} / ${c[2]}</span><span class="dots" aria-label="Chapter ${current+1} of ${chapters.length}">${chapters.map((_,i)=>`<i class="${i<=current?'on':''}"></i>`).join('')}</span></div><div class="lesson-heading"><div><h1>${c[3]}</h1><p>${c[4]}</p></div></div><div id="chapter-content" class="scene"></div><footer class="lesson-footer">${current?`<a class="btn subtle" href="#${chapters[current-1][0]}">Previous</a>`:`<a class="source-link" href="#check">Sources & self-check</a>`}${current<chapters.length-1?`<a class="btn primary" href="#${chapters[current+1][0]}">Next: ${chapters[current+1][1]}</a>`:`<a class="btn primary" href="${topic}">Back to topic</a>`}</footer>`;(renderers[c[0]]||overview)();}
function overview(){let stage=0;const labels=['Tokenize','Embed','Transform','Predict'];const explanations=['Split text into reusable pieces. Real tokenizers also encode spaces, punctuation, and fragments of words.','Look up a learned vector for each token. The vector width stays fixed through the residual stream.','Repeat attention and feed-forward updates. Causal attention lets each position use only the present and past.','Map the last position to a score for every vocabulary token. Softmax turns scores into a next-token distribution.'];$('#chapter-content').innerHTML=lab('A sentence, through the network',`<div class="token-row"><span class="token">The</span><span class="token">cat</span><span class="token">sat</span><span class="token active">?</span></div><div id="overview-diagram"></div><div class="stepper" id="stages">${labels.map((l,i)=>`<button data-stage="${i}">${String(i+1).padStart(2,'0')} ${l}</button>`).join('')}</div><p class="stage-info" id="stage-info"></p>`,`<span>Explore each stage, or watch the signal move.</span><button class="btn subtle" id="play">Play walkthrough</button>`)+insight('A transformer repeatedly updates <b>one vector per token</b>. The final vectors become predictions. “Understanding” is learned across these updates; there is no separate dictionary of meanings.')+details('How does this relate to the original transformer?',`<p>The 2017 model used an <b>encoder</b> to read a source sequence in both directions and a <b>decoder</b> to generate a target sequence. Decoder cross-attention reads the encoder output. This lesson starts with the causal, decoder-only pattern common in language models.</p><div class="mini-stack"><span class="node blue">Source → encoder</span><span class="op">+</span><span class="node green">Past target → decoder</span><span class="op">=</span><span class="node">Next target token</span></div><p style="margin-top:15px">Encoder-only models are useful for representations. Decoder-only models generate continuations. Encoder–decoder models explicitly separate reading and generating.</p>`);function draw(){activate('#stages',stage);$('#stage-info').textContent=explanations[stage];$('#overview-diagram').innerHTML=svg(`<defs><marker id="arr" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#64764e"/></marker></defs>${labels.map((l,i)=>{const x=35+i*200;return `${i<3?`<path class="${i===stage?'path-line':''}" d="M${x+145} 126 H${x+195}" stroke="#66764c" marker-end="url(#arr)"/>`:''}<rect x="${x}" y="76" width="145" height="102" rx="8" fill="${stage===i?'#2b3921':'#1c2220'}" stroke="${stage===i?'#c5f277':'#424c40'}"/><text x="${x+72}" y="105" text-anchor="middle" class="${stage===i?'lime':'bright'}">${l}</text>${i===0?`<text x="${x+72}" y="145" text-anchor="middle">[12, 48, 91]</text>`:i===1?Array.from({length:9},(_,j)=>`<rect x="${x+30+j%3*30}" y="${117+Math.floor(j/3)*14}" width="24" height="9" rx="2" fill="#c5f277" opacity="${.2+(j%4)*.2}"/>`).join(''):i===2?`<rect x="${x+22}" y="118" width="101" height="17" rx="3" fill="#354727"/><rect x="${x+22}" y="141" width="101" height="17" rx="3" fill="#39465a"/><text x="${x+72}" y="205" text-anchor="middle">× many layers</text>`:`<text x="${x+72}" y="135" text-anchor="middle" class="lime">on  62%</text><text x="${x+72}" y="156" text-anchor="middle">by  24%</text>`}`}).join('')}`,'Four stages: tokenize, embed, transform, predict','0 0 820 240')};let timer;$('#stages').onclick=e=>{if(e.target.dataset.stage!==undefined){stage=+e.target.dataset.stage;draw()}};$('#play').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('#play').textContent='Play walkthrough'}else{stage=(stage+1)%4;draw();timer=setInterval(()=>{stage=(stage+1)%4;draw()},1700);$('#play').textContent='Pause walkthrough'}};cleanup=()=>clearInterval(timer);draw();}
function tokens(){
 let selected=1,mode=0;const examples=[['The','cat','sat','on','the','mat'],['un','believ','able','!'],['bank','of','the','river']];
 const embedding=t=>Array.from({length:8},(_,i)=>Math.sin([...t].reduce((s,c)=>s+c.charCodeAt(0),0)*(i+1)*.073));
 $('#chapter-content').innerHTML=lab('From symbols to vectors',`<div class="controls" style="justify-content:space-between;margin-bottom:25px"><label class="control">Example<select id="token-example"><option>A sentence</option><option>Subword pieces</option><option>Meaning in context</option></select></label>${tabs('embedding-mode',['Lookup','After context'])}</div><div id="token-experiment"></div>`,`<span>Click a token to inspect its vector.</span><span>Toy tokenizer · 8 dimensions</span>`)+insight('An embedding is a learned <b>starting point</b>, not a fixed definition. After attention, the same token can have different representations in different contexts.')+details('What is actually learned?',`<p>A vocabulary of V tokens and width d gives an embedding table E with shape V × d. Token ID i selects row E[i]. IDs are arbitrary labels: ID 48 is not “more cat” than ID 12.</p><div class="formula">token ID i → E[i] ∈ ℝᵈ → contextual updates → hᵢ ∈ ℝᵈ</div><p>Dimensions generally do not correspond to neatly named concepts. This diagram uses deterministic toy vectors, not embeddings from a trained model. “After context” adds a toy update to show the distinction.</p>`)+details('Why not one token per word?',`<p>A finite vocabulary cannot list every word, name, or spelling. Subword tokenizers reuse pieces; byte-based fallbacks can represent unusual text. The splits here are hand-picked examples, not the output of a production tokenizer.</p>`);
 function draw(){const ts=examples[+$('#token-example').value||0];selected=Math.min(selected,ts.length-1);const v=embedding(ts[selected]);const contextual=v.map((x,i)=>x+(mode?.32*Math.cos(i+selected+ts.length):0));$('#token-experiment').innerHTML=`<div class="token-row">${ts.map((t,i)=>`<button class="token ${selected===i?'active':''}" data-token="${i}">${t}<small>ID ${[...t].reduce((s,c)=>s+c.charCodeAt(0),0)}</small></button>`).join('')}</div><div class="caption">${mode?'Context changes the representation':'Select one row of the embedding table'}</div><div class="matrix" style="grid-template-columns:70px repeat(8,minmax(15px,1fr));max-width:650px">${ts.map((t,r)=>`<span class="matrix-label" style="color:${r===selected?'var(--green)':'var(--muted)'}">${t}</span>${embedding(t).map((x,j)=>`<div class="cell ${r===selected?'selected':''}" style="background:${x<0?`rgba(146,201,236,${.1+Math.abs(x)*.4})`:`rgba(197,242,119,${.1+Math.abs(x)*.4})`}" title="${t}, dimension ${j+1}: ${x.toFixed(2)}">${r===selected?x.toFixed(1):''}</div>`).join('')}`).join('')}</div><div class="node ${mode?'blue':'green'}" style="margin:22px auto 0;max-width:650px"><small>${mode?'Contextual representation':'Selected embedding'} · ${ts[selected]}</small><div class="mono" style="font-size:.85rem;overflow-wrap:anywhere;margin-top:9px">[${contextual.map(v=>v.toFixed(2)).join(', ')}]</div></div>`;document.querySelectorAll('[data-token]').forEach(b=>b.onclick=()=>{selected=+b.dataset.token;draw()})}
 $('#token-example').innerHTML=['A sentence','Subword pieces','Meaning in context'].map((t,i)=>`<option value="${i}">${t}</option>`).join('');$('#token-example').onchange=()=>{selected=0;draw()};$('#embedding-mode').onclick=e=>{if(e.target.dataset.value!==undefined){mode=+e.target.dataset.value;activate('#embedding-mode',mode);draw()}};draw();
}
function attentionLab(){let row=5;const queryAngles=[0,40,80,120,160,30];$('#chapter-content').innerHTML=lab('The attention workbench',`<div class="controls" style="justify-content:space-between">${range('query-angle','Query direction',0,360,1,30,'°')}${range('attention-temp','Softmax temperature',.2,2,.1,1)}<label class="check"><input id="causal" type="checkbox" checked>Causal mask</label></div><div class="hint"><b>Try this</b><span>Select “sat”, then disable the mask. Future tokens can now leak into its prediction.</span></div><div class="token-row" id="query-tokens">${words.map((w,i)=>`<button class="token ${i===row?'active':''}" data-row="${i}">${w}</button>`).join('')}</div><div class="grid2" style="margin-top:25px"><div><div class="eyebrow muted">01 / Match query to keys</div><div id="qk-diagram"></div></div><div><div class="eyebrow muted" style="margin-bottom:23px">02 / Turn scores into weights</div><div id="attention-bars"></div></div></div><div class="math-grid" style="margin-top:18px"><div class="math-card"><div class="eyebrow">Query q</div><strong id="q-value"></strong></div><div class="math-card"><div class="eyebrow">Σ weights</div><strong id="sum-value"></strong></div><div class="math-card"><div class="eyebrow">03 / Mix values</div><strong id="out-value"></strong></div></div>`,`<span>Exact calculation on fixed 2D toy keys and values.</span><span id="mask-info"></span>`)+lab('One distribution for every query',`<div class="grid2"><div id="attention-matrix"></div><div style="align-self:center"><div class="eyebrow accent">Rows read columns</div><p style="margin-top:14px;color:var(--muted)">Each row is a different token’s attention distribution. Brighter cells carry more weight. Select a row to inspect that query above.</p><p class="note">The hatched triangle is the future. Turn off the causal mask to reveal it.</p><div class="formula">A: 6 queries × 6 keys<br>Y = A × V</div></div></div>`,`<span>The selected row matches the workbench. Other rows use fixed toy queries.</span>`)+insight('Attention is <b>content-dependent weighted averaging</b>. Queries and keys decide where to look; values carry the information that is read.')+details('Open the equation and tensor shapes',`<div class="formula">Q = XWQ, K = XWK, V = XWV<br><br>A = softmax((QKᵀ / √dₖ) + M)<br>Y = AV</div><p>For n tokens: X is n × d; Q and K are n × dₖ; V is n × dᵥ; A is n × n; Y is n × dᵥ. Softmax runs across each row. A causal mask M uses −∞ above the diagonal, giving future tokens exactly zero weight.</p><p>Dividing by √dₖ keeps dot-product magnitudes manageable as head width grows. The extra temperature control is an experiment; ordinary attention uses temperature 1 after that scaling.</p>`)+details('Inspect the actual numbers',`<div id="attention-numbers" class="table-wrap"></div>`)+details('Does an attention weight explain the model’s answer?',`<p>Only partly. A large weight shows a strong connection in this head, at this layer. Value vectors, output projections, other heads, residual paths, and later layers all matter. A heatmap alone is not a faithful explanation of a complete answer.</p>`);
 function draw(){const angle=+$('#query-angle').value*Math.PI/180,temp=+$('#attention-temp').value,causal=$('#causal').checked;queryAngles[row]=+$('#query-angle').value;const a=attention(angle,row,causal,temp);$('#query-angle-value').textContent=$('#query-angle').value+'°';$('#attention-temp-value').textContent=temp.toFixed(1);$('#q-value').textContent=`[${a.q.map(x=>x.toFixed(2)).join(', ')}]`;$('#sum-value').textContent=a.weights.reduce((s,w)=>s+w,0).toFixed(3);$('#out-value').textContent=`[${a.output.map(x=>x.toFixed(2)).join(', ')}]`;$('#mask-info').textContent=causal?`${row+1} of 6 positions visible`:'All 6 positions visible';$('#attention-bars').innerHTML=bars(words,a.weights);$('#attention-matrix').innerHTML=`<div class="matrix" style="grid-template-columns:40px repeat(6,minmax(25px,1fr));gap:4px"><span></span>${words.map(w=>`<span class="matrix-label">${w}</span>`).join('')}${words.map((w,r)=>{const dist=attention(queryAngles[r]*Math.PI/180,r,causal,temp);return `<button class="matrix-label" data-matrix-row="${r}" style="background:transparent;border:0;color:${r===row?'var(--green)':'var(--muted)'}" aria-label="Inspect query ${w}, position ${r+1}">${w}</button>${dist.weights.map((weight,col)=>`<button data-matrix-row="${r}" class="cell ${causal&&col>r?'masked':''} ${r===row?'selected':''}" style="background-color:rgba(197,242,119,${causal&&col>r?0:.08+weight*.75})" aria-label="${w} at position ${r+1} reads ${words[col]} at position ${col+1}: ${(weight*100).toFixed(1)} percent">${causal&&col>r?'—':Math.round(weight*100)}</button>`).join('')}`}).join('')}</div><p class="caption">Weights in percent · each row sums to 100% before rounding</p>`;document.querySelectorAll('[data-matrix-row]').forEach(b=>b.onclick=()=>{row=+b.dataset.matrixRow;$('#query-angle').value=queryAngles[row];document.querySelectorAll('[data-row]').forEach(x=>x.classList.toggle('active',+x.dataset.row===row));draw()});$('#qk-diagram').innerHTML=svg(`<circle cx="160" cy="130" r="89" fill="none" stroke="#353f37"/><line x1="45" y1="130" x2="280" y2="130" stroke="#303833"/><line x1="160" y1="20" x2="160" y2="240" stroke="#303833"/>${keys.map((k,i)=>`<line x1="160" y1="130" x2="${160+k[0]*88}" y2="${130-k[1]*88}" stroke="${causal&&i>row?'#414643':'#92c9ec'}" opacity="${causal&&i>row?.3:.6}"/><circle cx="${160+k[0]*88}" cy="${130-k[1]*88}" r="4" fill="#92c9ec" opacity="${causal&&i>row?.2:1}"/><text x="${160+k[0]*109}" y="${135-k[1]*109}" text-anchor="middle">${words[i]}</text>`).join('')}<line x1="160" y1="130" x2="${160+a.q[0]*48}" y2="${130-a.q[1]*48}" stroke="#c5f277" stroke-width="3"/><circle cx="${160+a.q[0]*48}" cy="${130-a.q[1]*48}" r="5" fill="#c5f277"/><text x="315" y="100" class="lime">q</text><text x="315" y="126" class="blue">keys</text>`,'Query direction compared to six keys','0 0 370 260');$('#attention-numbers').innerHTML=`<table><thead><tr><th>Key</th><th>q · k / √2</th><th>Weight</th><th>Value</th></tr></thead><tbody>${words.map((w,i)=>`<tr><td>${w}</td><td>${a.scores[i]===-Infinity?'−∞ (masked)':a.scores[i].toFixed(3)}</td><td>${a.weights[i].toFixed(3)}</td><td>[${values[i].join(', ')}]</td></tr>`).join('')}</tbody></table>`;}
 $('#query-tokens').onclick=e=>{const b=e.target.closest('[data-row]');if(b){row=+b.dataset.row;$('#query-angle').value=queryAngles[row];document.querySelectorAll('[data-row]').forEach(x=>x.classList.toggle('active',+x.dataset.row===row));draw()}};['query-angle','attention-temp','causal'].forEach(id=>$('#'+id).oninput=draw);draw();
}
function heads(){let head=0;$('#chapter-content').innerHTML=lab('Parallel attention patterns',`<div class="controls" style="justify-content:space-between">${tabs('head-select',['Head 1','Head 2','Head 3'])}<label class="check"><input type="checkbox" id="all-heads">Show all heads</label></div><div id="heads-diagram"></div><div id="heads-result" class="insight"></div>`,`<span>Illustrative projections; head roles are learned, not assigned.</span><span>3 heads × 2 dimensions</span>`)+insight('Heads compute <b>different mixtures in parallel</b>. Their results are concatenated, then a learned output projection mixes them back into the model’s width.')+details('Why not just one wider head?',`<p>One head produces one attention distribution per query. Multiple heads can route information with different distributions at the same time. They need not align with human categories such as “grammar” or “facts”. Some heads learn overlapping patterns.</p><div class="formula">headₕ = Attention(XWQₕ, XWKₕ, XWVₕ)<br>MultiHead(X) = Concat(head₁, …, headₕ) WO<br><br>(n × 2) × 3 heads → n × 6 → n × d</div><p>All heads read the same input X, using their own learned projections. The miniature head outputs here use the earlier toy values; the final WO projection is shown schematically.</p>`);
 function draw(){activate('#head-select',head);const show=$('#all-heads').checked;const angles=[.2,2.1,4.2];const colors=['#c5f277','#92c9ec','#bbacf0'];const outputs=angles.map(a=>attention(a,5,true,.65));$('#heads-diagram').innerHTML=svg(`${[0,1,2].map(h=>{const x=20+h*265,active=show||head===h;return `<g opacity="${active?1:.24}"><text x="${x+115}" y="26" text-anchor="middle" fill="${colors[h]}">Head ${h+1}</text>${words.map((w,i)=>`<text x="${x+30+i*37}" y="54" text-anchor="middle" style="font-size:12px">${w}</text><path d="M${x+116} 172 Q${x+30+i*37} 130 ${x+30+i*37} 65" stroke="${colors[h]}" stroke-width="${1+outputs[h].weights[i]*10}" opacity="${.1+outputs[h].weights[i]}" fill="none"/>`).join('')}<rect x="${x+71}" y="172" width="92" height="39" rx="5" fill="#252c23" stroke="${colors[h]}"/><text x="${x+117}" y="197" text-anchor="middle" class="bright">mat</text><text x="${x+117}" y="242" text-anchor="middle">[${outputs[h].output.map(x=>x.toFixed(2)).join(', ')}]</text><path d="M${x+117} 253 V272 H402 V292" stroke="${colors[h]}" fill="none"/></g>`}).join('')}<rect x="268" y="293" width="270" height="42" rx="5" fill="#242c20" stroke="#657b49"/><text x="403" y="319" text-anchor="middle" class="lime">Concatenate → output projection</text>`,'Three attention heads, with distinct weighted connections, merged into one output','0 0 820 355');const top=outputs[head].weights.indexOf(Math.max(...outputs[head].weights));$('#heads-result').innerHTML=`Head ${head+1} places its largest weight on <b>“${words[top]}”</b> (${(outputs[head].weights[top]*100).toFixed(1)}%). Switch heads to see another distribution from the same input.`}
 $('#head-select').onclick=e=>{if(e.target.dataset.value!==undefined){head=+e.target.dataset.value;draw()}};$('#all-heads').onchange=draw;draw();
}
function block(){let stage=0;const stages=['Input','Normalize','Attention + add','Normalize','MLP + add'];const x=[.8,-.4,.2,1.1],update=[.2,.3,-.1,.1];
 $('#chapter-content').innerHTML=lab('Anatomy of a modern pre-norm block',`<div class="controls" style="justify-content:space-between">${range('update-scale','Update strength',0,2,.1,1)}<label class="check"><input id="residual" type="checkbox" checked>Residual connections</label></div><div id="block-diagram"></div><div class="stepper" id="block-stages">${stages.map((s,i)=>`<button data-stage="${i}">${s}</button>`).join('')}</div><div id="block-output"></div>`,`<span>Same width in, same width out. Repeat this block L times.</span><span>Toy numeric trace</span>`)+insight('The residual stream is a <b>shared workspace</b>. Attention adds information gathered from other positions; the MLP adds a nonlinear transformation at this position.')+details('What does the MLP do?',`<div class="formula">u = x + Attention(RMSNorm(x))<br>y = u + MLP(RMSNorm(u))<br><br>SwiGLU(z) = (SiLU(zWg) ⊙ zWu) Wd</div><p>The MLP expands the vector into more features, applies a nonlinearity, and projects back. A gate such as SwiGLU controls which features contribute. Unlike attention, the MLP does not directly mix token positions; the same weights act independently at every position.</p><p>The diagram’s small MLP uses tanh with fixed toy coefficients for an inspectable trace. The equation shows a common modern gated alternative. Residual connections aid information and gradient flow; they do not freeze the representation.</p>`)+details('Why normalize? What changed since 2017?',`<p>RMSNorm rescales activations using their root-mean-square magnitude, with a learned per-dimension gain. LayerNorm also subtracts the mean. This toy RMSNorm uses gain 1.</p><p>The original transformer used LayerNorm after each residual addition. Many later models normalize before each sublayer, often with RMSNorm, to improve training behavior at depth. The choice is architectural, not a universal rule.</p>`);
 function draw(){const s=+$('#update-scale').value,res=$('#residual').checked;$('#update-scale-value').textContent=s.toFixed(1);const norm=rmsNorm(x),u=x.map((v,i)=>(res?v:0)+update[i]*s),un=rmsNorm(u),mlp=un.map((v,i)=>Math.tanh(v*.7+un[(i+1)%4]*.3)*s*.4),y=u.map((v,i)=>(res?v:0)+mlp[i]);const traces=[x,norm,u,un,y];activate('#block-stages',stage);$('#block-diagram').innerHTML=svg(`<path d="M60 160 H760" stroke="#46563b" stroke-width="2"/>${res?`<path d="M76 160 V65 H390 V160 M409 160 V65 H714 V160" fill="none" stroke="#c5f277"/><text x="230" y="52" class="lime" text-anchor="middle">residual path</text><text x="558" y="52" class="lime" text-anchor="middle">residual path</text>`:''}${[['RMSNorm',113,1,'#92c9ec'],['Attention',237,2,'#c5f277'],['RMSNorm',442,3,'#92c9ec'],['MLP',568,4,'#bbacf0']].map(([label,pos,idx,color])=>`<rect x="${pos}" y="126" width="106" height="68" rx="6" fill="${stage===idx?'#30382a':'#1d2420'}" stroke="${stage===idx?color:'#475044'}"/><text x="${pos+53}" y="166" text-anchor="middle" class="bright">${label}</text>`).join('')}<circle cx="390" cy="160" r="17" fill="#20271b" stroke="#728950"/><text x="390" y="165" text-anchor="middle" class="lime">${res?'+':'='}</text><circle cx="714" cy="160" r="17" fill="#20271b" stroke="#728950"/><text x="714" y="165" text-anchor="middle" class="lime">${res?'+':'='}</text><text x="59" y="226">x</text><text x="750" y="226">y</text><text x="290" y="226" text-anchor="middle">mix positions</text><text x="620" y="226" text-anchor="middle">mix features</text>`,'Pre-norm transformer block with two residual connections','0 0 820 260');$('#block-output').innerHTML=`<div class="node green"><small>${stages[stage]} · vector at this point</small><div class="mono" style="margin-top:7px">[${traces[stage].map(v=>v.toFixed(3)).join(', ')}]</div></div><p class="caption">${s===0?(res?'Updates are zero: the residual path preserves x exactly.':'Updates are zero and no residual path remains: the output becomes zero.'):'Set update strength to zero, then toggle residual connections.'}</p>`;}
 $('#block-stages').onclick=e=>{if(e.target.dataset.stage!==undefined){stage=+e.target.dataset.stage;draw()}};$('#update-scale').oninput=draw;$('#residual').onchange=draw;draw();
}
function position(){
 $('#chapter-content').innerHTML=lab('Rotary position embeddings',`<div class="controls" style="justify-content:space-between">${range('query-position','Query position m',0,12,1,4)}${range('key-position','Key position n',0,12,1,2)}${range('shared-shift','Shift both positions',0,12,1,0)}</div><div id="rope-diagram"></div><div class="math-grid"><div class="math-card"><div class="eyebrow">Relative distance</div><strong id="rope-distance"></strong></div><div class="math-card"><div class="eyebrow">Rotated q · k</div><strong id="rope-dot"></strong></div><div class="math-card"><div class="eyebrow">Pair frequency θ</div><strong>0.5 rad</strong></div></div>`,`<span>One coordinate pair of a larger query and key.</span><a class="source-link" href="https://arxiv.org/abs/2104.09864" target="_blank" rel="noopener">RoFormer · 2021</a>`)+insight('RoPE rotates query and key coordinate pairs by position. Their dot product depends on <b>relative offset</b>: move both equally and their match stays the same.')+details('Why does the shared shift cancel?',`<div class="formula">q′ = R(mθ)q, k′ = R(nθ)k<br>q′ᵀk′ = qᵀR((n − m)θ)k</div><p>R is a 2D rotation. Real heads apply it to multiple coordinate pairs using different frequencies. Here q = [1, 0] and k = [0.8, 0.6]. Because their content differs, the match is not simply the cosine of the positional distance.</p><p>RoPE changes Q and K, not the basic attention rule. Extending its position range usually needs scaling or training adjustments; rotating farther does not automatically give reliable long-context reasoning.</p>`)+details('Other ways to represent position',`<p>The original transformer added sinusoidal vectors to token embeddings. Learned absolute embeddings assign a trained vector to each position. Relative position biases instead add distance-dependent terms to attention scores. A causal mask also supplies directional structure, but does not replace a precise positional signal.</p>`);
 function draw(){const m=+$('#query-position').value,n=+$('#key-position').value,shift=+$('#shared-shift').value,q=rotate([1,0],(m+shift)*.5),k=rotate([.8,.6],(n+shift)*.5);['query-position','key-position','shared-shift'].forEach(id=>$('#'+id+'-value').textContent=$('#'+id).value);$('#rope-distance').textContent=`${n-m} tokens`;$('#rope-dot').textContent=dot(q,k).toFixed(4);$('#rope-diagram').innerHTML=svg(`<g transform="translate(255 135)"><circle r="97" fill="none" stroke="#3d473b"/><line x1="-125" x2="125" stroke="#303b30"/><line y1="-125" y2="125" stroke="#303b30"/>${[[q,'#c5f277','q′'],[k,'#92c9ec','k′']].map(([v,c,label])=>`<line x2="${v[0]*95}" y2="${-v[1]*95}" stroke="${c}" stroke-width="3"/><circle cx="${v[0]*95}" cy="${-v[1]*95}" r="5" fill="${c}"/><text x="${v[0]*116}" y="${-v[1]*116+5}" text-anchor="middle" style="fill:${c}">${label}</text>`).join('')}</g><text x="485" y="98" class="lime">Query position: ${m+shift}</text><text x="485" y="133" class="blue">Key position: ${n+shift}</text><text x="485" y="186">Shift both. Watch the angle stay fixed.</text>`,'Rotating query and key vectors with a shared position shift','0 0 820 280');}['query-position','key-position','shared-shift'].forEach(id=>$('#'+id).oninput=draw);draw();
}
function learning(){
 let mode=0,steps=0,logits=[.1,.6,-.2,.3],generated=[];const candidates=['on','near','under','beside'];
 const generationWords=[...candidates,'the','mat','.'];
 function generationLogits(){const last=generated.at(-1);if(!last)return [...logits,-2,-2,-3];if(candidates.includes(last))return [-3,-3,-3,-3,3,.5,-2];if(last==='the')return [-3,-3,-3,-3,-2,3,-1];return [-2,-2,-2,-2,-2,-2,3];}
 $('#chapter-content').innerHTML=lab('Training and inference',`<div class="controls" style="justify-content:space-between">${tabs('learning-mode',['Train','Generate'])}${range('sample-temp','Sampling temperature',.1,2,.1,.8)}</div><div id="learning-scene"></div><div class="controls" style="margin-top:24px"><button class="btn primary" id="learning-step">Take a gradient step</button><button class="btn subtle" id="learning-reset">Reset experiment</button><span class="small" id="learning-status" role="status"></span></div>`,`<span id="learning-disclosure"></span>`)+insight('During training, <b>the parameters change</b>. During generation, <b>the context changes</b>. A model’s forward computation is reused in both.')+details('How does a next-token task teach so much?',`<p>Training shifts a sequence by one position: input “The cat sat” has targets “cat sat on”. The causal mask prevents seeing the answer. All positions can be trained in parallel because the complete example is known.</p><div class="formula">L = −(1/n) Σᵢ log p(xᵢ₊₁ | x₁ … xᵢ)<br>θ ← θ − η ∇θ L</div><p>Backpropagation sends the loss gradient through the output projection, blocks, and embeddings. Across varied data, useful syntax, facts, and abstractions can reduce prediction error. Loss is a training objective, not a direct measure of truth or understanding.</p><p>This experiment isolates the last step: it learns four output biases for one fixed context. Its gradient is p − target. A real model trains many weight matrices over many examples.</p>`)+details('What about instruction following and reasoning?',`<p>Pretraining learns broad prediction patterns. Supervised fine-tuning uses demonstrations. Preference optimization or reinforcement learning changes which outputs are rewarded. These are training procedures, not necessarily new attention architectures.</p><p>At inference, a system may spend more computation generating intermediate tokens, trying candidates, checking results, or using tools. More computation can help, but does not guarantee correctness. The reasoning path is still generated output.</p><a class="source-link" href="https://arxiv.org/abs/2501.12948" target="_blank" rel="noopener">DeepSeek-R1 · reinforcement learning for reasoning</a>`);
 function draw(){const t=+$('#sample-temp').value;$('#sample-temp-value').textContent=t.toFixed(1);$('#sample-temp').disabled=mode===0;activate('#learning-mode',mode);const p=softmax(mode?generationLogits():logits,mode?t:1);$('#learning-step').textContent=mode?'Sample next token':'Take a gradient step';$('#learning-step').disabled=mode&&(generated.length>=8||generated.at(-1)==='.');$('#learning-status').textContent=mode?`${generated.length} toy samples · weights fixed${generated.at(-1)==='.'?' · complete':''}`:`${steps} updates · parameters change`;$('#learning-disclosure').textContent=mode?'A toy transition model recomputes probabilities from the last token; not a transformer.':'Exact gradient descent on four output biases, learning rate 0.5.';$('#learning-scene').innerHTML=`<div class="token-row" style="margin-top:30px"><span class="token">The</span><span class="token">cat</span><span class="token">sat</span>${mode?generated.map(w=>`<span class="token active">${w}</span>`).join(''):'<span class="token active">on<small>known target</small></span>'}</div><div class="grid2" style="margin-top:35px"><div><div class="eyebrow muted" style="margin-bottom:18px">${mode?'Sampling distribution':'Predicted next token'}</div>${bars(mode?generationWords:candidates,p)}</div><div class="node ${mode?'blue':'green'}" style="display:flex;justify-content:center;align-items:center;flex-direction:column;gap:12px"><span class="eyebrow">${mode?'Inference':'Cross-entropy loss'}</span><strong style="font:500 2.7rem var(--display)">${mode?'θ fixed':(-Math.log(p[0])).toFixed(3)}</strong><span class="small">${mode?'New context, new distribution.':'−log p(“on”) · lower is better'}</span></div></div><p class="caption">${mode?'Each sampled token feeds back into the next prediction. Temperature changes randomness.':'Watch probability move toward the target as the loss falls.'}</p>`;}
 $('#learning-mode').onclick=e=>{if(e.target.dataset.value!==undefined){mode=+e.target.dataset.value;draw()}};$('#sample-temp').oninput=draw;$('#learning-step').onclick=()=>{if(mode){const p=softmax(generationLogits(),+$('#sample-temp').value);let r=Math.random(),idx=p.length-1;for(let i=0;i<p.length;i++){r-=p[i];if(r<=0){idx=i;break}}generated.push(generationWords[idx]);}else{const p=softmax(logits);logits=logits.map((l,i)=>l-.5*(p[i]-(i===0?1:0)));steps++}draw()};$('#learning-reset').onclick=()=>{steps=0;logits=[.1,.6,-.2,.3];generated=[];draw()};draw();
}
function efficiency(){let mode=0,tile=0;const names=['MHA','GQA','MQA','MLA'];$('#chapter-content').innerHTML=lab('KV cache: remember previous work',`<div class="controls" style="justify-content:space-between">${tabs('cache-mode',names)}${range('context-power','Context length',10,18,1,14)}</div><div id="cache-diagram"></div><div class="math-grid"><div class="math-card"><div class="eyebrow">KV cache / sequence</div><strong id="cache-size"></strong></div><div class="math-card"><div class="eyebrow">Relative to MHA</div><strong id="cache-ratio"></strong></div><div class="math-card"><div class="eyebrow">Query heads</div><strong>32</strong></div></div><p class="caption" id="cache-description"></p>`,`<span>32 layers · head width 128 · BF16 (2 bytes) · batch 1</span><span>Cache only, not total memory</span>`)+lab('FlashAttention: change the execution, keep the attention',`<div class="grid2"><div id="flash-grid"></div><div><div class="eyebrow accent">Tile, compute, combine</div><p style="margin-top:15px;color:var(--muted);font-size:.95rem">Load small blocks into fast on-chip memory. Update a running softmax and weighted sum. Avoid writing the full attention matrix to GPU memory.</p><div class="formula">Same dense attention result*<br>Less memory traffic<br>Still O(n²) pairwise work</div><button class="btn subtle" id="next-tile">Process next tile</button></div></div>`,`<span>*Up to floating-point differences. Diagram shows score tiles, not GPU scheduling.</span><a class="source-link" href="https://arxiv.org/abs/2205.14135" target="_blank" rel="noopener">FlashAttention · 2022</a>`)+insight('These techniques solve different bottlenecks: <b>KV caching avoids recomputation</b>, GQA/MQA/MLA reduce stored state, and FlashAttention reduces memory traffic.')+details('What does the cache store? Why does it grow?',`<p>At each layer, earlier keys and values are saved. A new token computes its own Q/K/V, then its query reads the cached past. Earlier causal token representations are unchanged when a later token arrives.</p><div class="formula">KV bytes = 2 × batch × tokens × layers × KV heads × head width × bytes/element</div><p>Prefill processes the prompt, with O(n²) dense attention work. Each subsequent decoding step attends over the growing context in O(n) attention work. Generating n new tokens still accumulates quadratic attention work overall.</p><p>Model weights, activations, allocator overhead, and serving buffers are excluded. GQA here shares 8 KV heads among 32 query heads; MQA shares one. The MLA toy budget is 512 latent coordinates plus 64 rotary-key coordinates per token/layer. Its actual sizes depend on the model.</p>`)+details('What is latent attention compressing?',`<p>GQA shares explicit keys and values across query heads. Multi-head latent attention instead caches a lower-dimensional learned representation, with separate positional information. Efficient algebra can absorb some reconstruction into projection matrices.</p><p>That is compression across feature dimensions. The token-wise compression in later architectures also reduces how many past representations are retained; these are distinct choices.</p><a class="source-link" href="https://arxiv.org/abs/2412.19437" target="_blank" rel="noopener">DeepSeek-V3 technical report</a>`);
 function draw(){activate('#cache-mode',mode);const n=2**+$('#context-power').value;$('#context-power-value').textContent=(n/1024)+'K tokens';const baseMem=cacheBytes(n,32);const size=mode===3?n*32*(512+64)*2:cacheBytes(n,[32,8,1][mode]);$('#cache-size').textContent=(size/1024**3).toFixed(2)+' GiB';$('#cache-ratio').textContent=(size/baseMem*100).toFixed(1)+'%';$('#cache-description').textContent=['Each query head has its own key/value head.','Four query heads share each key/value head.','All query heads share one key/value head.','Cache a compressed latent vector plus a positional key component.'][mode];const groups=[8,4,1,1][mode];$('#cache-diagram').innerHTML=svg(`<text x="80" y="48">Queries</text><text x="80" y="175">${mode===3?'Latent cache':'KV groups'}</text>${Array.from({length:8},(_,i)=>{const qx=235+i*68;const gx=mode===0?qx:mode===1?270+Math.floor(i/2)*136:475;return `<rect x="${qx-19}" y="24" width="38" height="37" rx="5" fill="#2c3820" stroke="#87a657"/><text x="${qx}" y="49" text-anchor="middle" class="lime">Q</text><path d="M${qx} 61 V103 L${gx} 153" stroke="#63794e" fill="none"/>`}).join('')}${Array.from({length:groups},(_,i)=>{const x=mode===0?235+i*68:mode===1?270+i*136:475;return `<rect x="${x-(mode===3?110:23)}" y="153" width="${mode===3?220:46}" height="43" rx="5" fill="#1d2a31" stroke="#688fa5"/><text x="${x}" y="180" text-anchor="middle" class="blue">${mode===3?'latent + RoPE key':'KV'}</text>`}).join('')}<text x="475" y="234" text-anchor="middle">Schematic grouping · calculator uses 32 query heads</text>`,'Query heads sharing key/value caches','0 0 820 255');}
 function drawTile(){$('#flash-grid').innerHTML=`<div class="eyebrow muted" style="margin-bottom:16px">Attention scores · conceptual 16 × 16</div><div class="matrix" style="grid-template-columns:repeat(16,1fr);gap:3px;margin:0">${Array.from({length:256},(_,i)=>{const r=Math.floor(i/16),c=i%16,active=Math.floor(r/4)*4+Math.floor(c/4)===tile;return `<span style="aspect-ratio:1;border-radius:2px;background:${active?'#c5f277':'#293128'}"></span>`}).join('')}</div><p class="caption">Tile ${tile+1} / 16 · only a small score block is materialized</p>`}
 $('#cache-mode').onclick=e=>{if(e.target.dataset.value!==undefined){mode=+e.target.dataset.value;draw()}};$('#context-power').oninput=draw;$('#next-tile').onclick=()=>{tile=(tile+1)%16;drawTile()};draw();drawTile();
}
function experts(){let token=0;const examples=['river','function','bonjour'];const routerLogits=[[2.1,.4,-.3,1.6,.8,-.4,.2,.6],[.1,2.2,.9,-.4,1.7,.3,.6,-.2],[.4,-.2,2.1,.2,.1,1.7,.5,.9]];
 $('#chapter-content').innerHTML=lab('Route a token through a sparse MLP',`<div class="controls" style="justify-content:space-between">${tabs('expert-token',examples)}${range('top-k','Active experts (top-k)',1,4,1,2)}</div><div class="mini-stack" style="margin:28px 0"><div class="node blue">Token representation</div><span class="op">→</span><div class="node green">Learned router</div></div><div id="expert-grid" class="expert-grid"></div><div class="mini-stack" style="margin:25px 0"><span class="op">↓</span><div class="node green">Weighted sum of selected outputs</div></div><div class="math-grid"><div class="math-card"><div class="eyebrow">Total experts</div><strong>8</strong></div><div class="math-card"><div class="eyebrow">Active this token</div><strong id="expert-count"></strong></div><div class="math-card"><div class="eyebrow">Expert work vs dense*</div><strong id="expert-fraction"></strong></div></div>`,`<span>*Equal-sized expert MLPs only; routing, attention, and communication excluded.</span>`)+insight('MoE separates <b>total parameter capacity</b> from <b>parameters active per token</b>. It saves expert computation, but the full model still needs storage and efficient routing.')+details('How does top-k routing work?',`<div class="formula">s = softmax(x Wr)<br>S = indices of the k largest scores<br>y = Σₑ∈S normalized(sₑ) · Expertₑ(x)</div><p>Each expert is a feed-forward network. The toy router renormalizes the selected probabilities to sum to one. Real routers can use other scoring, normalization, shared experts, and balancing mechanisms.</p><p>Experts are not manually named disciplines. Routing depends on the contextual vector, not merely the token’s spelling. The three examples here use fixed illustrative router logits.</p>`)+details('What makes MoE hard?',`<p>If every token selects the same experts, hardware becomes imbalanced and unused experts learn little. Systems use balancing objectives or routing adjustments. Distributed experts also require communication, which can erase theoretical compute savings.</p><p>DeepSeek-V3 combines shared and routed experts, uses a balancing strategy without the usual auxiliary balancing loss at its core, and trains with a multi-token prediction objective. Its 671B total / 37B activated parameter count illustrates why those two numbers must be distinguished.</p><a class="source-link" href="https://arxiv.org/abs/2412.19437" target="_blank" rel="noopener">DeepSeek-V3 technical report</a>`);
 function draw(){const k=+$('#top-k').value,selected=routeExperts(routerLogits[token],k);activate('#expert-token',token);$('#top-k-value').textContent=k;$('#expert-count').textContent=k+' / 8';$('#expert-fraction').textContent=k/8*100+'%';$('#expert-grid').innerHTML=Array.from({length:8},(_,i)=>{const s=selected.find(x=>x.i===i);return `<div class="expert ${s?'active':''}"><strong>E${i+1}</strong><span>${s?(s.w*100).toFixed(1)+'% mixture weight':'inactive'}</span></div>`}).join('');}$('#expert-token').onclick=e=>{if(e.target.dataset.value!==undefined){token=+e.target.dataset.value;draw()}};$('#top-k').oninput=draw;draw();
}
const milestones=[
 {year:'2017',name:'The original transformer',label:'The foundation',text:'An encoder reads the source. A causal decoder generates a target, using cross-attention to the encoder. Attention replaces recurrence in this translation architecture.',nodes:['Source embeddings + position','Encoder: attention → MLP','Decoder: masked attention → cross-attention → MLP','Vocabulary probabilities'],chips:['Encoder–decoder','Sinusoidal position','Multi-head attention'],url:'https://arxiv.org/abs/1706.03762'},
 {year:'2021–23',name:'A more efficient decoder',label:'A family of improvements',text:'RoPE supplies relative position. GQA reduces KV-cache size. Gated MLPs and pre-normalization refine the block. FlashAttention accelerates exact attention through better memory use.',nodes:['Token embedding','RMSNorm → GQA + RoPE → residual','RMSNorm → gated MLP → residual','Final norm → vocabulary projection'],chips:['RoPE','GQA','Gated MLP','FlashAttention'],url:'https://arxiv.org/abs/2305.13245'},
 {year:'2024',name:'DeepSeek-V3',label:'Sparse capacity + compressed state',text:'MoE activates a subset of feed-forward capacity. MLA compresses the cached key/value representation. Multi-token prediction adds a training objective for future tokens.',nodes:['Token embedding','Multi-head latent attention','Shared expert + selected routed experts','Output + auxiliary multi-token training'],chips:['671B total / 37B active','MLA','MoE'],url:'https://arxiv.org/abs/2412.19437'},
 {year:'2025',name:'Reasoning is another axis',label:'Training & inference, not a block diagram',text:'DeepSeek-R1 explores reinforcement learning for reasoning. A model can improve how it uses computation without replacing its underlying attention architecture.',nodes:['Pretrained model','Post-training: demonstrations + reinforcement learning','Inference: intermediate tokens, checking, tools','Final answer'],chips:['Post-training','Inference computation','Architecture ≠ capability'],url:'https://arxiv.org/abs/2501.12948'},
 {year:'2026 / Qwen',name:'Qwen3.5-397B-A17B',label:'Recurrent + attention hybrid',text:'Its 60-layer language stack repeats three Gated DeltaNet layers and one gated attention layer, all with MoE. A vision encoder adds visual inputs. Some layers retain state; others attend over token history.',nodes:['Text tokens + vision encoder features','3 × (Gated DeltaNet → MoE)','1 × (gated attention → MoE)','Repeat group 15 times → output'],chips:['397B total / 17B active','3:1 hybrid','Vision + language'],url:'https://huggingface.co/Qwen/Qwen3.5-397B-A17B'},
 {year:'2026 / V4',name:'DeepSeek-V4',label:'Compress the token history',text:'Compressed Sparse Attention and Heavily Compressed Attention reduce long-context costs. Manifold-constrained hyper-connections extend residual connections. This is more than a larger V3.',nodes:['Token representations','Compressed Sparse / Heavily Compressed Attention','MoE + manifold-constrained hyper-connections','Multi-token prediction modules'],chips:['Token-wise compression','Sparse reads','Extended residual paths'],url:'https://arxiv.org/abs/2606.19348'},
 {year:'2026 / Sep',name:'DeepSeek-V4.1-Flash',label:'Different budgets for input and output',text:'The September announcement describes a causal encoder–decoder with 552B total parameters: 8B active for input, 16B for output, plus native visual understanding. Input processing and output generation get asymmetric computation.',nodes:['Text + visual inputs','Causal encoder · 8B active','Decoder · 16B active','Generated output'],chips:['Asymmetric architecture','552B total','Native vision'],url:'https://deepseek.com/en/news/deepseek-v4-1-flash/'}
];
function frontier(){let selected=4,mechanism=0,systems=0;
 $('#chapter-content').innerHTML=lab('An architectural field guide',`<div class="year-tabs" id="milestone-tabs" role="group" aria-label="Architecture milestones">${milestones.map((m,i)=>`<button data-milestone="${i}">${m.year}</button>`).join('')}</div><div id="milestone-detail"></div>`,`<span>Selected public examples, not a ranking or exhaustive release list.</span><span>Checked 06 Oct 2026</span>`)+lab('Three ways to keep the past',`<div class="controls" style="justify-content:space-between">${tabs('memory-mechanism',['Full attention','Recurrent state','Compressed + sparse'])}${range('history-size','Past tokens',8,64,8,24)}</div><div id="memory-scene"></div><div class="insight" id="memory-insight"></div>`,`<span>Conceptual memory units; not parameter counts or benchmark measurements.</span>`)+lab('The architecture is only one part of the system',`<div>${tabs('system-view',['Multimodal inputs','Test-time computation'])}</div><div id="system-diagram"></div><p class="caption" id="system-caption"></p>`,`<span>Schematic patterns. Implementations vary by model.</span>`)+insight('Read a model through four questions: <b>how does it mix tokens, what does it retain, which weights activate, and how is it trained and used?</b> A model name alone answers none of these.')+details('What is a recurrent or linear-attention layer retaining?',`<p>Full attention keeps token-specific keys and values for later queries. A recurrent layer folds the past into a fixed-size state. That bounds state memory per layer, but retrieving an arbitrary old detail can be harder.</p><div class="formula">State intuition: Sₜ = update(Sₜ₋₁, xₜ)<br>Readout: yₜ = read(Sₜ, xₜ)</div><p>Selective state-space models such as Mamba and linear-attention families such as Gated DeltaNet use different update rules. They are not identical architectures. A hybrid can interleave such layers with full attention to trade efficiency against detailed retrieval.</p><p>“Fixed state” describes those recurrent layers, not an entire hybrid: its full-attention layers still retain a growing cache. Parallel or chunked training algorithms can coexist with recurrent decoding.</p><a class="source-link" href="https://arxiv.org/abs/2312.00752" target="_blank" rel="noopener">Mamba · selective state spaces</a> · <a class="source-link" href="https://arxiv.org/abs/2405.21060" target="_blank" rel="noopener">Mamba-2 · state-space duality</a>`)+details('How do compression and sparsity differ?',`<p><b>Compression</b> merges information into fewer stored representations. <b>Sparsity</b> chooses which representations to read. A sliding window reads only nearby tokens; a learned sparse selector can also retrieve distant ones. Combining a local window, summaries, and selected remote context is one useful pattern.</p><p>The toy diagram groups every eight old tokens into a summary and selects two summaries plus four recent tokens. This illustrates the distinction; it does not reproduce DeepSeek’s kernels, selection rule, or compression ratios.</p>`)+details('What should I assume about closed frontier models?',`<p>Only what their publishers disclose. Product behavior, benchmarks, or a model name do not reveal the number of experts, attention type, hidden width, or exact topology. This lesson uses public reports and configurations for concrete diagrams rather than guessing proprietary internals.</p><p>Nor does one configuration define the whole frontier: data, optimization, multimodal training, post-training, context management, tools, and inference budgets can change capability independently.</p>`);
 function drawMilestone(){document.querySelectorAll('[data-milestone]').forEach(b=>{b.classList.toggle('active',+b.dataset.milestone===selected);b.setAttribute('aria-pressed',+b.dataset.milestone===selected)});const m=milestones[selected];$('#milestone-detail').innerHTML=`<div class="frontier-info"><div><span class="eyebrow accent">${m.label}</span><h2>${m.name}</h2><p>${m.text}</p><div class="chip-row">${m.chips.map(c=>`<span class="chip">${c}</span>`).join('')}</div><a class="source-link" href="${m.url}" target="_blank" rel="noopener">Read the primary source</a></div><div class="architecture-stack">${m.nodes.map((n,i)=>`<div class="node ${i===1?'green':i===2?'purple':''}">${n}</div>${i<3?'<span class="muted" style="text-align:center;line-height:1">↓</span>':''}`).join('')}</div></div>`;}
 function drawMemory(){activate('#memory-mechanism',mechanism);const n=+$('#history-size').value;$('#history-size-value').textContent=n;const recent=4,groups=Math.ceil((n-recent)/8),stored=mechanism===0?n:mechanism===1?4:groups+recent,read=mechanism===0?n:mechanism===1?4:Math.min(2,groups)+recent;$('#memory-scene').innerHTML=`<div class="eyebrow muted" style="margin:25px 0 12px">${n} past token representations</div><div class="signal-grid">${Array.from({length:n},(_,i)=>`<span class="${mechanism===0||i>=n-4?'lit':''}" title="Token ${i+1}"></span>`).join('')}</div><div style="text-align:center;color:var(--muted);padding:12px">↓ ${['keep each one','fold into state','summarize older groups; retain recent tokens'][mechanism]}</div><div class="signal-grid" style="max-width:${mechanism===1?160:600}px;margin:auto;grid-template-columns:repeat(${Math.min(stored,16)},1fr)">${Array.from({length:stored},(_,i)=>`<span class="${i<read?'lit':''}" title="Stored unit ${i+1}"></span>`).join('')}</div><div class="controls" style="justify-content:center;margin:24px 0"><span class="stat"><strong>${stored}</strong><small>stored units</small></span><span class="stat"><strong>${read}</strong><small>units read by a query</small></span></div>`;$('#memory-insight').textContent=['Direct access to every past token. Double the history: double the cache and the work of this decoding attention step.','A fixed-size state summarizes history. Doubling the history does not grow this state, but information must share limited capacity.','Compression reduces stored units; sparse selection reduces reads. A model may miss details that are compressed away or not selected.'][mechanism];}
 function drawSystem(){activate('#system-view',systems);$('#system-diagram').innerHTML=systems?svg(`<g fill="#20291c" stroke="#69884a">${['Prompt','Generate candidates','Check / tool','Answer'].map((s,i)=>`<rect x="${20+i*204}" y="80" width="174" height="65" rx="6"/>`).join('')}</g>${['Prompt','Generate candidates','Check / tool','Answer'].map((s,i)=>`<text x="${107+i*204}" y="118" text-anchor="middle" class="bright" style="font-size:13px">${s}</text>${i<3?`<path d="M${194+i*204} 111 H${223+i*204}" stroke="#7e9e57"/>`:''}`).join('')}<path d="M516 147 V193 H311 V148" stroke="#c5f277" fill="none" class="path-line"/><text x="412" y="220" text-anchor="middle" class="lime">Spend more inference computation</text>`,'Generate, check and revise candidates during inference','0 0 820 245'):svg(`${[['Image patches',30,'#92c9ec'],['Audio segments',310,'#bbacf0'],['Text tokens',590,'#c5f277']].map(([s,x,c])=>`<rect x="${x}" y="28" width="200" height="53" rx="6" fill="#222827" stroke="${c}"/><text x="${x+100}" y="61" text-anchor="middle" class="bright">${s}</text><path d="M${x+100} 81 V117 H410 V151" stroke="${c}" fill="none"/>`).join('')}<rect x="200" y="152" width="420" height="57" rx="6" fill="#293321" stroke="#9dbc71"/><text x="410" y="186" text-anchor="middle" class="lime">Encoded features → sequence model</text>`,'Image, audio and text representations brought into a sequence model','0 0 820 235');$('#system-caption').textContent=systems?'A system can improve by generating, verifying, and revising—not only by changing its attention blocks.':'Encoders or learned projections turn modalities into compatible representations. Not every multimodal model supports every modality.';}
 $('#milestone-tabs').onclick=e=>{if(e.target.dataset.milestone!==undefined){selected=+e.target.dataset.milestone;drawMilestone()}};$('#memory-mechanism').onclick=e=>{if(e.target.dataset.value!==undefined){mechanism=+e.target.dataset.value;drawMemory()}};$('#history-size').oninput=drawMemory;$('#system-view').onclick=e=>{if(e.target.dataset.value!==undefined){systems=+e.target.dataset.value;drawSystem()}};drawMilestone();drawMemory();drawSystem();
}
const references=[
 ['2017','Attention Is All You Need','Original encoder–decoder and scaled dot-product attention','https://arxiv.org/abs/1706.03762'],
 ['2020','GLU Variants Improve Transformer','Gated feed-forward layers','https://arxiv.org/abs/2002.05202'],
 ['2021','RoFormer','Rotary position embeddings','https://arxiv.org/abs/2104.09864'],
 ['2022','FlashAttention','Exact attention with less memory traffic','https://arxiv.org/abs/2205.14135'],
 ['2023','Grouped-query attention','Sharing keys and values across query heads','https://arxiv.org/abs/2305.13245'],
 ['2023','Mamba','Selective state-space sequence models','https://arxiv.org/abs/2312.00752'],
 ['2024','Mamba-2 / state-space duality','Connections between SSMs and attention variants','https://arxiv.org/abs/2405.21060'],
 ['2024','DeepSeek-V3 technical report','MLA, sparse experts, multi-token prediction','https://arxiv.org/abs/2412.19437'],
 ['2025','DeepSeek-R1','Reasoning-oriented reinforcement learning','https://arxiv.org/abs/2501.12948'],
 ['2026','Qwen3.5-397B-A17B model card','Published hybrid layout and exact configuration','https://huggingface.co/Qwen/Qwen3.5-397B-A17B'],
 ['2026','DeepSeek-V4 technical report','Compressed sparse attention and hyper-connections','https://arxiv.org/abs/2606.19348'],
 ['2026','DeepSeek-V4.1-Flash announcement','September causal encoder–decoder disclosure','https://deepseek.com/en/news/deepseek-v4-1-flash/']
];
const questions=[
 ['A token gives another token a large attention weight. What is mixed into the result?',['The other token’s ID','Its value vector','Its key vector'],1,'Keys are used to compute the weights. Values are the information being averaged.','attention'],
 ['Why mask future positions when training a language model?',['To prevent access to the answer being predicted','To avoid updating parameters','To make all attention weights equal'],0,'The known training sequence includes future answers. A causal mask prevents this information from leaking into earlier predictions.','attention'],
 ['You set both sublayer updates to zero. With residual paths, the block outputs…',['Zero','A random embedding','Its input, unchanged'],2,'The block adds updates to its input. With zero updates, the identity path carries the input through.','block'],
 ['What changes in ordinary autoregressive inference?',['The learned weights after each token','The context and KV cache','The number of experts in the model'],1,'The parameters stay fixed; generated tokens extend the context and add cached keys and values.','learning'],
 ['FlashAttention makes dense attention…',['Exact, with less memory traffic','Sparse, by removing most token pairs','Linear in total pairwise compute'],0,'It computes dense attention in tiles with online softmax, avoiding the full score matrix in GPU memory. The pairwise work is still quadratic.','efficiency'],
 ['A recurrent–attention hybrid has constant total cache size. True?',['Yes, all old tokens become one vector','No, its full-attention layers can still have growing caches','Only if it uses more experts'],1,'The recurrent layers have bounded state. The retained full-attention layers still store token history.','frontier'],
 ['A 600B-parameter MoE uses 30B active parameters per token. Which follows?',['Only 30B parameters need storage','Every token executes all 600B weights','Compute and total capacity are different quantities'],2,'Selective activation saves compute. In general, the system still stores the full model, and routing has overhead.','experts']
];
function check(){let index=0,answers=Array(questions.length).fill(null);$('#chapter-content').innerHTML=lab('A quick check of your mental model',`<div id="quiz-scene"></div>`,`<span>No score to chase. Use the explanation to find what to revisit.</span>`)+insight('You now have a map: <b>represent → route information → transform features → predict</b>. Modern architectures mostly change the cost, capacity, memory, and training of that process.')+details('Primary sources · 12 papers and model disclosures',`<p style="margin-bottom:15px">Snapshot checked 6 October 2026. Dates identify the work or disclosure; later revisions may differ. The newest example is a September 2026 announcement, not a claim that all frontier internals are public.</p><div class="source-list">${references.map(r=>`<a class="source-item" href="${r[3]}" target="_blank" rel="noopener"><span>${r[1]}<small style="display:block;margin-top:5px">${r[2]}</small></span><span class="accent mono">${r[0]}</span></a>`).join('')}</div>`)+details('What these experiments simplify',`<p>All numerical demonstrations are small, hand-built educational models. They are not traces from a pretrained language model. Tokenization examples are illustrative. Dimensions, weights, router scores, and memory units are chosen for clarity.</p><p>Attention, softmax, rotary dot products, the training gradient, routing normalization, and cache arithmetic are computed from the displayed controls. Architectural diagrams omit many implementation details. A diagram’s layer count or relative size is not a model’s hidden configuration unless explicitly labeled.</p>`)+details('Explain it back to yourself',`<p>Pick a sentence and trace one token. Where does its first vector come from? Which positions can it read? What changes after attention? After the MLP? What does the output projection predict?</p><p>Now double the context. Identify what grows in dense attention, the KV cache, and a recurrent state. Finally, separate an MoE change from an RL training change. If you can explain those distinctions, you understand the core architecture rather than just its vocabulary.</p>`);
 function draw(){const q=questions[index],a=answers[index];$('#quiz-scene').innerHTML=`<div class="chapter-meta"><span class="eyebrow accent">Question ${index+1} / ${questions.length}</span><span class="small">${answers.filter(x=>x!==null).length} explored</span></div><h2 style="margin:20px 0 24px;font-size:1.4rem">${q[0]}</h2><div class="quiz-options">${q[1].map((o,i)=>`<button data-answer="${i}" class="${a!==null&&i===q[2]?'correct':a===i?'wrong':''}" ${a!==null?'disabled':''}>${o}</button>`).join('')}</div>${a!==null?`<div class="insight" style="margin-top:20px" role="status"><b>${a===q[2]?'Exactly.':'Not quite.'}</b> ${q[3]} <a class="source-link" href="#${q[4]}">Revisit experiment</a></div>`:''}<div class="controls" style="margin-top:25px;justify-content:space-between"><button class="btn subtle" id="quiz-prev" ${index===0?'disabled':''}>Previous question</button>${index<questions.length-1?'<button class="btn primary" id="quiz-next">Next question</button>':'<button class="btn primary" id="quiz-restart">Try again</button>'}</div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[index]=+b.dataset.answer;draw()});$('#quiz-prev').onclick=()=>{index--;draw()};if($('#quiz-next'))$('#quiz-next').onclick=()=>{index++;draw()};if($('#quiz-restart'))$('#quiz-restart').onclick=()=>{answers.fill(null);index=0;draw()};}draw();
}
const renderers={overview,tokens,attention:attentionLab,heads,block,position,learning,efficiency,experts,frontier,check};
if(isLesson){shell();window.addEventListener('hashchange',()=>{renderChapter();window.scrollTo({top:0,behavior:'instant'})})}else library();
